def transform(grid):
    n = len(grid)
    m = len(grid[0])

    def rotate_cw(a):
        return [list(row) for row in zip(*a[::-1])]

    def rotate_ccw(a):
        return [list(row) for row in zip(*a)][::-1]

    def rotate_180(a):
        return [row[::-1] for row in a[::-1]]

    quadrants = [
        grid,
        rotate_cw(grid),
        rotate_ccw(grid),
        rotate_180(grid),
    ]
    out = [[0] * (2 * m) for _ in range(2 * n)]
    for r in range(n):
        for c in range(m):
            out[r][c] = quadrants[0][r][c]
            out[r][c + m] = quadrants[1][r][c]
            out[r + n][c] = quadrants[2][r][c]
            out[r + n][c + m] = quadrants[3][r][c]
    return out
